// n8n Code node — "01-03: Intake, Documents, Reconciliation"
// Mode: Run Once for All Items. Expects the webhook body at items[0].json.body
// (Mode A: direct JSON; Mode B: same shape produced by the questionnaire frontend).
//
// DOCUMENT PROCESSING: multipart uploads are extracted upstream by native n8n
// Extract From File nodes (PDF/XLSX/XLS/CSV/TXT/ODS/RTF). The resulting
// documents[] objects contain fields[] for deterministic reconciliation.
// Image-only/scanned PDFs are flagged as extractionFailed rather than guessed.
// An OCR/vision provider can be added later without changing the financial engine.

const raw = $input.first().json.body || $input.first().json;

// ---------- normalize ----------
function toNumberOrNull(v) {
  if (v === null || v === undefined || v === '' || v === "I don't know" || v === 'Not sure') return null;
  const n = typeof v === 'number' ? v : Number(String(v).replace(/[₹,\s]/g, ''));
  return Number.isFinite(n) ? n : null;
}
function normalizeTenure(value, unit) {
  const n = toNumberOrNull(value);
  if (n === null) return null;
  if (unit === 'years') return Math.round(n * 12);
  return Math.round(n);
}
function normalizeInput(r) {
  return {
    business: {
      type: r?.business?.type ?? null,
      monthlySales: toNumberOrNull(r?.business?.monthlySales),
      monthlyExpenses: toNumberOrNull(r?.business?.monthlyExpenses),
      customersPayingLate: r?.business?.customersPayingLate ?? 'Not sure',
      receivablesAmount: toNumberOrNull(r?.business?.receivablesAmount),
      incomeOutlook: r?.business?.incomeOutlook ?? 'Not sure',
      cashReserve: toNumberOrNull(r?.business?.cashReserve),
    },
    loans: Array.isArray(r?.loans)
      ? r.loans.map((l, i) => ({
          id: l.id || `loan_${i + 1}`,
          lender: l.lender ?? null,
          loanType: l.loanType ?? "Don't know",
          outstandingAmount: toNumberOrNull(l.outstandingAmount),
          emi: toNumberOrNull(l.emi),
          remainingTenureMonths: normalizeTenure(l.remainingTenure, l.remainingTenureUnit),
          interestRatePct: toNumberOrNull(l.interestRatePct),
          secured: l.secured ?? null,
        }))
      : [],
    mainProblem: r?.mainProblem ?? "I'm not sure",
    urgency: r?.urgency ?? "I'm not sure",
    documents: Array.isArray(r?.documents) ? r.documents : [],
    businessName: r?.businessName ?? null,
  };
}

// ---------- validate ----------
function validateInput(data) {
  const errors = [];
  const warnings = [];
  if (data.business.monthlySales === null) warnings.push({ field: 'monthlySales', message: 'Monthly sales not provided.' });
  if (data.business.monthlyExpenses === null) warnings.push({ field: 'monthlyExpenses', message: 'Monthly expenses not provided.' });
  if (data.business.monthlySales !== null && data.business.monthlySales < 0) errors.push({ field: 'monthlySales', message: 'Monthly sales cannot be negative.' });
  if (data.business.monthlyExpenses !== null && data.business.monthlyExpenses < 0) errors.push({ field: 'monthlyExpenses', message: 'Monthly expenses cannot be negative.' });
  if (!Array.isArray(data.loans) || data.loans.length === 0) {
    warnings.push({ field: 'loans', message: 'No loans provided.' });
  } else {
    data.loans.forEach((l) => {
      if (l.emi === null) warnings.push({ field: `${l.id}.emi`, message: `EMI missing for loan ${l.id}.` });
      if (l.outstandingAmount === null) warnings.push({ field: `${l.id}.outstandingAmount`, message: `Outstanding amount missing for loan ${l.id}.` });
      if (l.emi !== null && l.emi < 0) errors.push({ field: `${l.id}.emi`, message: 'EMI cannot be negative.' });
      if (l.outstandingAmount !== null && l.outstandingAmount < 0) errors.push({ field: `${l.id}.outstandingAmount`, message: 'Outstanding amount cannot be negative.' });
      if (l.interestRatePct !== null && (l.interestRatePct < 0 || l.interestRatePct > 60)) errors.push({ field: `${l.id}.interestRatePct`, message: 'Interest rate looks invalid.' });
    });
  }
  return { isValid: errors.length === 0, errors, warnings };
}

// ---------- reconciliation ----------
function sumEMI(loans) {
  const known = (loans || []).filter((l) => l.emi !== null);
  if (known.length === 0) return null;
  return known.reduce((s, l) => s + l.emi, 0);
}
function sumOutstanding(loans) {
  const known = (loans || []).filter((l) => l.outstandingAmount !== null);
  if (known.length === 0) return null;
  return known.reduce((s, l) => s + l.outstandingAmount, 0);
}
function reconcile(userData, extractedDoc) {
  const conflicts = [];
  const confirmations = [];
  if (!extractedDoc || extractedDoc.extractionFailed || !Array.isArray(extractedDoc.fields) || extractedDoc.fields.length === 0) {
    return {
      documentType: extractedDoc?.documentType || 'unknown',
      fileName: extractedDoc?.fileName || null,
      conflicts,
      confirmations,
      hasConflicts: false,
      extractionFailed: !!extractedDoc?.extractionFailed || (extractedDoc && extractedDoc.fields && extractedDoc.fields.length === 0),
    };
  }
  const TOLERANCE = 0.03;
  const userLookup = {
    monthlyEMI: sumEMI(userData.loans),
    totalOutstanding: sumOutstanding(userData.loans),
    monthlySales: userData.business.monthlySales,
  };
  extractedDoc.fields.forEach((f) => {
    if (!(f.field in userLookup)) return;
    const userValue = userLookup[f.field];
    const docValue = toNumberOrNull(f.value);
    if (userValue === null || docValue === null) return;
    const diffRatio = userValue === 0 ? (docValue === 0 ? 0 : 1) : Math.abs(userValue - docValue) / Math.abs(userValue);
    const record = {
      field: f.field,
      userValue,
      documentValue: docValue,
      source: f.source,
      confidence: f.confidence,
      diffPct: Math.round(diffRatio * 1000) / 10,
    };
    if (diffRatio > TOLERANCE) conflicts.push({ ...record, status: 'CONFLICT', actionRequired: true });
    else confirmations.push({ ...record, status: 'CONFIRMED', actionRequired: false });
  });
  return {
    documentType: extractedDoc.documentType || 'unknown',
    fileName: extractedDoc.fileName || null,
    conflicts,
    confirmations,
    hasConflicts: conflicts.length > 0,
    extractionFailed: false,
  };
}

// ---------- run ----------
const data = normalizeInput(raw);
const validation = validateInput(data);
const reconciliationResults = (data.documents || []).map((doc) => reconcile(data, doc));
const anyExtractionFailed = reconciliationResults.some((r) => r.extractionFailed);
const anyConflicts = reconciliationResults.some((r) => r.hasConflicts);

return [
  {
    json: {
      data,
      validation,
      reconciliationResults,
      anyExtractionFailed,
      anyConflicts,
    },
  },
];

// ================================================================
// RESTRUCTRA — 04-06 Financial Engine, Scenarios, Diagnosis
// ================================================================
// n8n Code node
//
// HARD RULE:
// This node is deterministic.
// No LLM calculations happen here.
//
// Financial numbers are calculated only by this code.
// ================================================================

const input = $input.first().json;


// ================================================================
// 1. HELPERS
// ================================================================

function round2(n) {
  if (n === null || n === undefined) return null;
  if (!Number.isFinite(Number(n))) return null;
  return Math.round(Number(n) * 100) / 100;
}

function toNumberOrNull(v) {
  if (
    v === null ||
    v === undefined ||
    v === "" ||
    v === "I don't know" ||
    v === "Not sure"
  ) {
    return null;
  }

  const n =
    typeof v === "number"
      ? v
      : Number(String(v).replace(/[₹,\s]/g, ""));

  return Number.isFinite(n) ? n : null;
}

function normalizeTenure(value, unit) {
  const n = toNumberOrNull(value);

  if (n === null) return null;

  if (unit === "years") {
    return Math.round(n * 12);
  }

  return Math.round(n);
}


// ================================================================
// 2. NORMALIZE INPUT
// ================================================================

function normalizeInput(raw) {
  const out = {
    business: {
      type: raw?.business?.type ?? null,
      monthlySales: toNumberOrNull(
        raw?.business?.monthlySales
      ),
      monthlyExpenses: toNumberOrNull(
        raw?.business?.monthlyExpenses
      ),
      customersPayingLate:
        raw?.business?.customersPayingLate ?? "Not sure",
      receivablesAmount: toNumberOrNull(
        raw?.business?.receivablesAmount
      ),
      incomeOutlook:
        raw?.business?.incomeOutlook ?? "Not sure",
      cashReserve: toNumberOrNull(
        raw?.business?.cashReserve
      ),
    },

    loans: Array.isArray(raw?.loans)
      ? raw.loans.map((l, i) => ({
          id: l?.id || `loan_${i + 1}`,
          lender: l?.lender ?? null,
          loanType: l?.loanType ?? "Don't know",
          outstandingAmount: toNumberOrNull(
            l?.outstandingAmount
          ),
          emi: toNumberOrNull(l?.emi),
          remainingTenureMonths: normalizeTenure(
            l?.remainingTenure,
            l?.remainingTenureUnit
          ),
          interestRatePct: toNumberOrNull(
            l?.interestRatePct
          ),
          secured: l?.secured ?? null,
        }))
      : [],

    mainProblem:
      raw?.mainProblem ?? "I'm not sure",

    urgency:
      raw?.urgency ?? "I'm not sure",

    documents:
      Array.isArray(raw?.documents)
        ? raw.documents
        : [],
  };

  return out;
}


// ================================================================
// 3. VALIDATION
// ================================================================

function validateInput(data) {
  const errors = [];
  const warnings = [];

  if (data.business.monthlySales === null) {
    warnings.push({
      field: "monthlySales",
      message: "Monthly sales not provided.",
    });
  }

  if (data.business.monthlyExpenses === null) {
    warnings.push({
      field: "monthlyExpenses",
      message: "Monthly expenses not provided.",
    });
  }

  if (
    data.business.monthlySales !== null &&
    data.business.monthlySales < 0
  ) {
    errors.push({
      field: "monthlySales",
      message: "Monthly sales cannot be negative.",
    });
  }

  if (
    data.business.monthlyExpenses !== null &&
    data.business.monthlyExpenses < 0
  ) {
    errors.push({
      field: "monthlyExpenses",
      message: "Monthly expenses cannot be negative.",
    });
  }

  if (
    !Array.isArray(data.loans) ||
    data.loans.length === 0
  ) {
    warnings.push({
      field: "loans",
      message: "No loans provided.",
    });
  } else {
    data.loans.forEach((l) => {

      if (l.emi === null) {
        warnings.push({
          field: `${l.id}.emi`,
          message: `EMI missing for loan ${l.id}.`,
        });
      }

      if (l.outstandingAmount === null) {
        warnings.push({
          field: `${l.id}.outstandingAmount`,
          message: `Outstanding amount missing for loan ${l.id}.`,
        });
      }

      if (l.emi !== null && l.emi < 0) {
        errors.push({
          field: `${l.id}.emi`,
          message: "EMI cannot be negative.",
        });
      }

      if (
        l.outstandingAmount !== null &&
        l.outstandingAmount < 0
      ) {
        errors.push({
          field: `${l.id}.outstandingAmount`,
          message: "Outstanding amount cannot be negative.",
        });
      }

      if (
        l.interestRatePct !== null &&
        (
          l.interestRatePct < 0 ||
          l.interestRatePct > 60
        )
      ) {
        errors.push({
          field: `${l.id}.interestRatePct`,
          message: "Interest rate looks invalid.",
        });
      }
    });
  }

  return {
    isValid: errors.length === 0,
    errors,
    warnings,
  };
}


// ================================================================
// 4. SUM LOANS
// ================================================================

function sumEMI(loans) {
  const known = (loans || []).filter(
    (l) => l.emi !== null
  );

  if (known.length === 0) return null;

  return known.reduce(
    (sum, l) => sum + l.emi,
    0
  );
}

function sumOutstanding(loans) {
  const known = (loans || []).filter(
    (l) => l.outstandingAmount !== null
  );

  if (known.length === 0) return null;

  return known.reduce(
    (sum, l) => sum + l.outstandingAmount,
    0
  );
}


// ================================================================
// 5. RECONCILIATION
// ================================================================

function reconcile(userData, extractedDoc) {

  const conflicts = [];
  const confirmations = [];

  if (
    !extractedDoc ||
    !Array.isArray(extractedDoc.fields)
  ) {
    return {
      conflicts,
      confirmations,
      hasConflicts: false,
    };
  }

  const TOLERANCE = 0.03;

  const userLookup = {
    monthlyEMI: sumEMI(userData.loans),
    totalOutstanding: sumOutstanding(userData.loans),
    monthlySales:
      userData.business.monthlySales,
  };

  extractedDoc.fields.forEach((f) => {

    if (!(f.field in userLookup)) return;

    const userValue = userLookup[f.field];
    const docValue = toNumberOrNull(f.value);

    if (
      userValue === null ||
      docValue === null
    ) {
      return;
    }

    const diffRatio =
      userValue === 0
        ? (docValue === 0 ? 0 : 1)
        : Math.abs(userValue - docValue) /
          Math.abs(userValue);

    const record = {
      field: f.field,
      userValue,
      documentValue: docValue,
      source: f.source,
      confidence: f.confidence,
      diffPct:
        Math.round(diffRatio * 1000) / 10,
    };

    if (diffRatio > TOLERANCE) {

      conflicts.push({
        ...record,
        status: "CONFLICT",
        actionRequired: true,
      });

    } else {

      confirmations.push({
        ...record,
        status: "CONFIRMED",
        actionRequired: false,
      });
    }
  });

  return {
    conflicts,
    confirmations,
    hasConflicts: conflicts.length > 0,
  };
}


// ================================================================
// 6. BUILD ALL RECONCILIATION RESULTS
// ================================================================

function buildReconciliationResults(data) {

  const results = [];

  for (const doc of data.documents || []) {

    const result = reconcile(data, doc);

    results.push({
      documentType:
        doc?.documentType ?? null,

      fileName:
        doc?.fileName ?? null,

      conflicts:
        result.conflicts || [],

      confirmations:
        result.confirmations || [],

      hasConflicts:
        result.hasConflicts || false,

      extractionFailed:
        !Array.isArray(doc?.fields),
    });
  }

  return results;
}


// ================================================================
// 7. FINANCIAL ENGINE
// ================================================================

function computeFinancials(data) {

  const sales =
    data.business.monthlySales;

  const expenses =
    data.business.monthlyExpenses;

  const loans =
    data.loans || [];

  const totalMonthlyEMI =
    sumEMI(loans);

  const totalOutstandingDebt =
    sumOutstanding(loans);

  const missingEMICount =
    loans.filter(
      (l) => l.emi === null
    ).length;

  const availableAfterExpenses =
    sales !== null &&
    expenses !== null
      ? round2(sales - expenses)
      : null;

  const availableAfterEMI =
    availableAfterExpenses !== null &&
    totalMonthlyEMI !== null
      ? round2(
          availableAfterExpenses -
          totalMonthlyEMI
        )
      : null;

  const internalDSCR =
    availableAfterExpenses !== null &&
    totalMonthlyEMI
      ? round2(
          availableAfterExpenses /
          totalMonthlyEMI
        )
      : null;

  const emiToSalesRatio =
    sales &&
    totalMonthlyEMI !== null
      ? round2(
          totalMonthlyEMI / sales
        )
      : null;

  const emiToAvailableRatio =
    availableAfterExpenses !== null &&
    availableAfterExpenses > 0 &&
    totalMonthlyEMI !== null
      ? round2(
          totalMonthlyEMI /
          availableAfterExpenses
        )
      : null;


  // --------------------------------------------------------------
  // CASH RESERVE COVERAGE
  // --------------------------------------------------------------
  //
  // This measures how many months of CURRENT EMI obligations
  // the reported cash reserve could cover.
  //
  // It is NOT operating-expense runway.
  // --------------------------------------------------------------

  const cashReserve =
    data.business.cashReserve;

  const cashReserveCoverageMonths =
    cashReserve !== null &&
    totalMonthlyEMI > 0
      ? round2(
          cashReserve /
          totalMonthlyEMI
        )
      : null;


  const receivables =
    data.business.receivablesAmount;

  const receivablesRatio =
    receivables !== null &&
    sales
      ? round2(
          receivables / sales
        )
      : null;


  // --------------------------------------------------------------
  // DEBT CONCENTRATION
  // --------------------------------------------------------------

  let debtConcentration = "UNKNOWN";

  const knownOutstanding =
    loans.filter(
      (l) =>
        l.outstandingAmount !== null
    );

  if (loans.length === 1) {

    debtConcentration =
      "SINGLE_LOAN";

  } else if (
    knownOutstanding.length >= 2 &&
    totalOutstandingDebt
  ) {

    const maxShare =
      Math.max(
        ...knownOutstanding.map(
          (l) =>
            l.outstandingAmount
        )
      ) / totalOutstandingDebt;

    debtConcentration =
      maxShare > 0.6
        ? "CONCENTRATED"
        : "DISTRIBUTED";
  }


  // --------------------------------------------------------------
  // WEIGHTED AVERAGE INTEREST RATE
  // --------------------------------------------------------------

  const rated =
    loans.filter(
      (l) =>
        l.interestRatePct !== null &&
        l.outstandingAmount !== null
    );

  let weightedAvgInterestRate =
    null;

  let interestRateAssumed =
    false;

  if (rated.length > 0) {

    const sumOut =
      rated.reduce(
        (sum, l) =>
          sum + l.outstandingAmount,
        0
      );

    weightedAvgInterestRate =
      round2(
        rated.reduce(
          (sum, l) =>
            sum +
            l.outstandingAmount *
            l.interestRatePct,
          0
        ) / sumOut
      );

  } else {

    weightedAvgInterestRate = 14.0;
    interestRateAssumed = true;
  }


  // --------------------------------------------------------------
  // WEIGHTED AVERAGE REMAINING TENURE
  // --------------------------------------------------------------

  const tenured =
    loans.filter(
      (l) =>
        l.remainingTenureMonths !== null &&
        l.outstandingAmount !== null
    );

  let weightedAvgTenureMonths =
    null;

  let tenureAssumed =
    false;

  if (tenured.length > 0) {

    const sumOut =
      tenured.reduce(
        (sum, l) =>
          sum + l.outstandingAmount,
        0
      );

    weightedAvgTenureMonths =
      Math.round(
        tenured.reduce(
          (sum, l) =>
            sum +
            l.outstandingAmount *
            l.remainingTenureMonths,
          0
        ) / sumOut
      );

  } else {

    weightedAvgTenureMonths = 36;
    tenureAssumed = true;
  }


  // --------------------------------------------------------------
  // COMFORTABLE EMI RANGE
  // --------------------------------------------------------------

  let comfortableEMIRange =
    null;

  if (
    availableAfterExpenses !== null &&
    availableAfterExpenses > 0
  ) {

    comfortableEMIRange = {

      lower:
        round2(
          availableAfterExpenses * 0.4
        ),

      upper:
        round2(
          availableAfterExpenses * 0.55
        ),

      basis:
        "Illustrative safety-cushion calculation: 40%-55% of estimated money left after business expenses. Not a lender-approved affordability limit.",
    };
  }


  return {

    totalMonthlyEMI,

    totalOutstandingDebt,

    missingEMICount,

    availableAfterExpenses,

    availableAfterEMI,

    internalDSCR,

    emiToSalesRatio,

    emiToAvailableRatio,

    cashReserveCoverageMonths,

    receivablesRatio,

    debtConcentration,

    weightedAvgInterestRate,

    interestRateAssumed,

    weightedAvgTenureMonths,

    tenureAssumed,

    comfortableEMIRange,
  };
}


// ================================================================
// 8. AMORTIZATION HELPERS
// ================================================================

function emiForLoan(
  principal,
  annualRatePct,
  tenureMonths
) {

  if (
    !principal ||
    !tenureMonths
  ) {
    return null;
  }

  const r =
    annualRatePct / 12 / 100;

  if (r === 0) {

    return round2(
      principal /
      tenureMonths
    );
  }

  const factor =
    Math.pow(
      1 + r,
      tenureMonths
    );

  return round2(
    (
      principal *
      r *
      factor
    ) /
    (factor - 1)
  );
}

function totalRepayment(
  emi,
  months
) {

  if (
    emi === null ||
    !months
  ) {
    return null;
  }

  return round2(
    emi * months
  );
}


// ================================================================
// 9. STRESS ASSUMPTIONS
// ================================================================

const STRESS_ASSUMPTIONS = {

  stressRevenueChangePct: -20,

  recoveryRevenueChangePct: 15,

  expensesHeldConstant: true,
};


// ================================================================
// 10. REVENUE STRESS HELPER
// ================================================================

function availableUnderRevenueChange(
  sales,
  expenses,
  changePct
) {

  if (
    sales === null ||
    expenses === null
  ) {
    return null;
  }

  const adjustedSales =
    sales *
    (1 + changePct / 100);

  return round2(
    adjustedSales -
    expenses
  );
}


// ================================================================
// 11. SCENARIO ENGINE
// ================================================================

function buildScenarios(
  data,
  fin
) {

  const sales =
    data.business.monthlySales;

  const expenses =
    data.business.monthlyExpenses;

  const outstanding =
    fin.totalOutstandingDebt;

  const rate =
    fin.weightedAvgInterestRate;

  const tenure =
    fin.weightedAvgTenureMonths;

  const currentEMI =
    fin.totalMonthlyEMI;


  const availBase =
    fin.availableAfterExpenses;

  const availStress =
    availableUnderRevenueChange(
      sales,
      expenses,
      STRESS_ASSUMPTIONS
        .stressRevenueChangePct
    );

  const availRecovery =
    availableUnderRevenueChange(
      sales,
      expenses,
      STRESS_ASSUMPTIONS
        .recoveryRevenueChangePct
    );


  function testCase(emi) {

    if (emi === null) {
      return null;
    }

    return {

      base:
        availBase !== null
          ? round2(
              availBase - emi
            )
          : null,

      stress:
        availStress !== null
          ? round2(
              availStress - emi
            )
          : null,

      recovery:
        availRecovery !== null
          ? round2(
              availRecovery - emi
            )
          : null,
    };
  }


  const scenarios = {};


  // --------------------------------------------------------------
  // CURRENT
  // --------------------------------------------------------------

  scenarios.current = {

    label:
      "Current repayment (no change)",

    emi:
      currentEMI,

    tenureMonths:
      tenure,

    estimatedRemainingRepayment:
      totalRepayment(
        currentEMI,
        tenure
      ),

    monthlySurplusDeficit:
      testCase(currentEMI),

    note:
      "Reflects the loan terms as currently reported.",
  };


  // --------------------------------------------------------------
  // LONGER REPAYMENT
  // --------------------------------------------------------------

  if (
    outstanding &&
    tenure &&
    rate !== null
  ) {

    scenarios.longerRepayment = {};

    [0.25, 0.5, 1.0]
      .forEach((extPct) => {

        const key =
          `extend_${Math.round(
            extPct * 100
          )}pct`;

        const newTenure =
          Math.round(
            tenure *
            (1 + extPct)
          );

        const newEMI =
          emiForLoan(
            outstanding,
            rate,
            newTenure
          );

        const currentTotal =
          totalRepayment(
            currentEMI,
            tenure
          );

        const newTotal =
          totalRepayment(
            newEMI,
            newTenure
          );

        scenarios
          .longerRepayment[key] = {

            label:
              `Extend remaining tenure by ${Math.round(
                extPct * 100
              )}%`,

            newTenureMonths:
              newTenure,

            newEMI:
              newEMI,

            emiReduction:
              currentEMI !== null &&
              newEMI !== null
                ? round2(
                    currentEMI -
                    newEMI
                  )
                : null,

            estimatedAdditionalInterest:
              newTotal !== null &&
              currentTotal !== null
                ? round2(
                    newTotal -
                    currentTotal
                  )
                : null,

            monthlySurplusDeficit:
              testCase(newEMI),

            disclaimer:
              "Illustrative scenario only. Actual terms depend on lender approval.",
          };
      });


    scenarios
      .longerRepayment
      .default =
      "extend_50pct";

  } else {

    scenarios.longerRepayment = {

      unavailable: true,

      reason:
        "Insufficient data (outstanding amount, tenure, or interest rate missing).",
    };
  }


  // --------------------------------------------------------------
  // TEMPORARY RELIEF
  // --------------------------------------------------------------

  if (
    outstanding &&
    tenure &&
    rate !== null
  ) {

    const reliefMonths = 3;

    const monthlyRate =
      rate / 12 / 100;

    const accruedInterest =
      round2(
        outstanding *
        monthlyRate *
        reliefMonths
      );

    const newPrincipal =
      round2(
        outstanding +
        accruedInterest
      );

    const postReliefTenure =
      tenure;

    const postReliefEMI =
      emiForLoan(
        newPrincipal,
        rate,
        postReliefTenure
      );


    scenarios.temporaryRelief = {

      label:
        "3-month illustrative payment relief",

      reliefMonths:

        reliefMonths,

      paymentDuringRelief:
        0,

      assumedInterestTreatment:
        "Interest continues to accrue during relief and is added to outstanding principal.",

      accruedInterestDuringRelief:
        accruedInterest,

      postReliefEMI:
        postReliefEMI,

      postReliefTenureMonths:
        postReliefTenure,

      totalTimelineMonths:
        postReliefTenure +
        reliefMonths,

      monthlySurplusDeficitDuringRelief:
        testCase(0),

      monthlySurplusDeficitAfterRelief:
        testCase(postReliefEMI),

      disclaimer:
        "Illustrative scenario only. The lender may or may not offer this exact structure.",
    };

  } else {

    scenarios.temporaryRelief = {

      unavailable: true,

      reason:
        "Insufficient data (outstanding amount, tenure, or interest rate missing).",
    };
  }


  // --------------------------------------------------------------
  // STEP-DOWN
  // --------------------------------------------------------------

  if (
    outstanding &&
    tenure &&
    rate !== null &&
    currentEMI !== null
  ) {

    const stepMonths = 6;

    const reducedEMI =
      round2(
        currentEMI * 0.6
      );

    const principalPaidInStep =
      round2(
        reducedEMI *
        stepMonths
      );

    const monthlyRate =
      rate / 12 / 100;

    const interestDuringStep =
      round2(
        outstanding *
        monthlyRate *
        stepMonths
      );

    const remainingPrincipalAfterStep =
      round2(
        Math.max(
          outstanding +
          interestDuringStep -
          principalPaidInStep,
          0
        )
      );

    const remainingTenureAfterStep =
      Math.max(
        tenure -
        stepMonths,
        1
      );

    const subsequentEMI =
      emiForLoan(
        remainingPrincipalAfterStep,
        rate,
        remainingTenureAfterStep
      );


    scenarios.stepDown = {

      label:
        "Reduced EMI for 6 months, then step up",

      stepMonths:

        stepMonths,

      reducedEMI:
        reducedEMI,

      subsequentEMI:
        subsequentEMI,

      subsequentTenureMonths:
        remainingTenureAfterStep,

      totalTimelineMonths:
        stepMonths +
        remainingTenureAfterStep,

      monthlySurplusDeficitDuringStep:
        testCase(reducedEMI),

      monthlySurplusDeficitAfterStep:
        testCase(subsequentEMI),

      simplification:
        "Principal/interest split during the step-down period is approximated, not a full amortization schedule.",

      disclaimer:
        "Illustrative scenario only. Actual terms depend on lender approval.",
    };

  } else {

    scenarios.stepDown = {

      unavailable: true,

      reason:
        "Insufficient data.",
    };
  }


  // --------------------------------------------------------------
  // CONSOLIDATION
  // --------------------------------------------------------------

  const loans =
    data.loans || [];

  if (loans.length >= 2) {

    const allHaveData =
      loans.every(
        (l) =>
          l.outstandingAmount !== null &&
          l.interestRatePct !== null &&
          l.remainingTenureMonths !== null
      );

    if (allHaveData) {

      const consolidatedTenure =
        Math.max(
          ...loans.map(
            (l) =>
              l.remainingTenureMonths
          )
        );

      const consolidatedEMI =
        emiForLoan(
          outstanding,
          rate,
          consolidatedTenure
        );

      const emiReductionPct =
        currentEMI
          ? round2(
              (
                (
                  currentEMI -
                  consolidatedEMI
                ) /
                currentEMI
              ) * 100
            )
          : null;

      const meaningfullyBeneficial =
        emiReductionPct !== null &&
        emiReductionPct >= 15;


      scenarios.consolidation = {

        label:
          "Consolidate all loans into a single facility",

        consolidatedOutstanding:
          outstanding,

        consolidatedEMI:
          consolidatedEMI,

        consolidatedTenureMonths:
          consolidatedTenure,

        emiReduction:
          currentEMI !== null
            ? round2(
                currentEMI -
                consolidatedEMI
              )
            : null,

        emiReductionPct:
          emiReductionPct,

        recommended:
          meaningfullyBeneficial,

        monthlySurplusDeficit:
          testCase(
            consolidatedEMI
          ),

        note:
          meaningfullyBeneficial
            ? "Calculated reduction is meaningful (>=15%). Presented as an option, not an automatic recommendation."
            : "Calculated benefit is not large enough to recommend consolidation on its own.",

        disclaimer:
          "Illustrative scenario only. Actual consolidated terms depend on lender approval.",
      };

    } else {

      scenarios.consolidation = {

        unavailable: true,

        reason:
          "Consolidation cannot be reliably assessed from the available information (missing rate/tenure/outstanding on at least one loan).",
      };
    }

  } else {

    scenarios.consolidation = {

      notApplicable: true,

      reason:
        "Only one loan reported.",
    };
  }


  return {

    scenarios,

    stressAssumptions:
      STRESS_ASSUMPTIONS,
  };
}


// ================================================================
// 12. STRESS DIAGNOSIS
// ================================================================

function diagnoseStress(
  data,
  fin,
  scenarioBundle
) {

  const classifications =
    new Set();

  const {
    internalDSCR,
    cashReserveCoverageMonths,
    receivablesRatio,
    emiToAvailableRatio,
    weightedAvgInterestRate,
    interestRateAssumed,
  } = fin;

  const loans =
    data.loans || [];


  const dscrKnown =
    internalDSCR !== null;

  const bufferKnown =
    cashReserveCoverageMonths !== null;


  // HEALTHY / WATCH

  if (
    dscrKnown &&
    internalDSCR >= 1.6 &&
    (
      !bufferKnown ||
      cashReserveCoverageMonths >= 2
    ) &&
    (
      receivablesRatio === null ||
      receivablesRatio < 0.3
    )
  ) {

    classifications.add(
      "HEALTHY"
    );

  } else if (
    dscrKnown &&
    internalDSCR >= 1.15
  ) {

    classifications.add(
      "WATCH"
    );
  }


  // HIGH EMI BURDEN

  if (
    emiToAvailableRatio !== null &&
    emiToAvailableRatio > 0.6
  ) {

    classifications.add(
      "HIGH_EMI_BURDEN"
    );
  }


  // TEMPORARY LIQUIDITY STRESS

  if (
    receivablesRatio !== null &&
    receivablesRatio > 0.35 &&
    ["Yes", "Sometimes"].includes(
      data.business.customersPayingLate
    )
  ) {

    classifications.add(
      "TEMPORARY_LIQUIDITY_STRESS"
    );
  }


  // SEASONAL

  if (
    data.mainProblem ===
    "My business is seasonal"
  ) {

    classifications.add(
      "SEASONAL_CASH_FLOW_STRESS"
    );
  }


  // HIGH INTEREST

  if (
    !interestRateAssumed &&
    weightedAvgInterestRate !== null &&
    weightedAvgInterestRate > 16
  ) {

    classifications.add(
      "HIGH_INTEREST_BURDEN"
    );
  }


  // MULTIPLE LOANS

  if (
    loans.length >= 3
  ) {

    classifications.add(
      "MULTIPLE_LOAN_COMPLEXITY"
    );
  }


  // SAFETY NET

  if (
    dscrKnown &&
    internalDSCR < 1.0 &&
    classifications.size === 0
  ) {

    classifications.add(
      "WATCH"
    );
  }


  // STRUCTURAL CASH FLOW CHECK

  if (
    scenarioBundle &&
    scenarioBundle.scenarios
  ) {

    const s =
      scenarioBundle.scenarios;

    const candidateBaseValues =
      [];


    if (
      s.current?.monthlySurplusDeficit?.base
      !== undefined
    ) {

      candidateBaseValues.push(
        s.current
          .monthlySurplusDeficit
          .base
      );
    }


    if (
      s.longerRepayment &&
      !s.longerRepayment.unavailable
    ) {

      Object.values(
        s.longerRepayment
      ).forEach((v) => {

        if (
          v &&
          typeof v === "object" &&
          v.monthlySurplusDeficit
        ) {

          candidateBaseValues.push(
            v.monthlySurplusDeficit.base
          );
        }
      });
    }


    if (
      s.temporaryRelief &&
      !s.temporaryRelief.unavailable
    ) {

      candidateBaseValues.push(
        s.temporaryRelief
          .monthlySurplusDeficitAfterRelief
          ?.base
      );
    }


    if (
      s.stepDown &&
      !s.stepDown.unavailable
    ) {

      candidateBaseValues.push(
        s.stepDown
          .monthlySurplusDeficitAfterStep
          ?.base
      );
    }


    if (
      s.consolidation &&
      !s.consolidation.unavailable &&
      !s.consolidation.notApplicable
    ) {

      candidateBaseValues.push(
        s.consolidation
          .monthlySurplusDeficit
          ?.base
      );
    }


    const validCandidates =
      candidateBaseValues.filter(
        (v) =>
          v !== null &&
          v !== undefined
      );


    if (
      validCandidates.length > 0
    ) {

      const bestBase =
        Math.max(
          ...validCandidates
        );

      if (
        bestBase < 0
      ) {

        classifications.add(
          "STRUCTURAL_CASH_FLOW_PROBLEM"
        );
      }
    }
  }


  if (
    classifications.size === 0
  ) {

    classifications.add(
      "WATCH"
    );
  }


  return Array.from(
    classifications
  );
}


// ================================================================
// 13. DATA CONFIDENCE
// ================================================================

function computeDataConfidence(
  data,
  validation,
  reconciliationResults,
  fin
) {

  let score = 100;


  score -=
    validation.warnings.length * 8;


  const conflictCount =
    (reconciliationResults || [])
      .reduce(
        (sum, r) =>
          sum +
          (
            r.conflicts
              ? r.conflicts.length
              : 0
          ),
        0
      );


  score -=
    conflictCount * 15;


  if (
    data.documents.length === 0
  ) {

    score -= 10;
  }


  if (
    fin &&
    fin.tenureAssumed
  ) {

    score -= 12;
  }


  if (
    fin &&
    fin.interestRateAssumed
  ) {

    score -= 12;
  }


  if (
    fin &&
    fin.missingEMICount > 0
  ) {

    score -=
      fin.missingEMICount * 10;
  }


  // --------------------------------------------------------------
  // IMPORTANT:
  // Never report absolute 100% certainty.
  // --------------------------------------------------------------

  score =
    Math.max(
      0,
      Math.min(
        95,
        score
      )
    );


  let level =
    "HIGH";


  if (
    score < 50
  ) {

    level =
      "LOW";

  } else if (
    score < 80
  ) {

    level =
      "MEDIUM";
  }


  return {

    score,

    level,

    note:
      "Confidence reflects the completeness and consistency of the supplied information. It does not mean the financial analysis is guaranteed to be correct.",
  };
}


