// ================================================================
// RESTRUCTRA — Validate & Parse Recommendation
// ================================================================
// n8n Code node
//
// Purpose:
// 1. Read the LLM response from Groq or Gemini
// 2. Parse the LLM JSON safely
// 3. Validate its structure
// 4. Verify financial figures against deterministic engine output
// 5. Reject unsafe lender-approval claims
// 6. Fail closed if anything cannot be verified
//
// HARD RULE:
// The LLM can explain deterministic calculations.
// The LLM cannot create, modify, or invent financial figures.
// ================================================================


// ================================================================
// 1. READ LLM RESPONSE
// ================================================================

const httpResponse = $input.first().json;


// ================================================================
// 2. RETRIEVE DETERMINISTIC CONTEXT
// ================================================================
//
// This is intentionally retrieved from the earlier deterministic
// node rather than relying on the HTTP Request node to carry all
// upstream data forward.
// ================================================================

const priorContext =
  ($node["04-06 Financial Engine, Scenarios, Diagnosis"] &&
    $node["04-06 Financial Engine, Scenarios, Diagnosis"].json) ||
  {};

const {
  data,
  validation,
  reconciliationResults,
  fin,
  scenarioBundle,
  classifications,
  dataConfidence,
} = priorContext;


// ================================================================
// 3. EXTRACT TEXT FROM LLM RESPONSE
// ================================================================
//
// Supports:
//
// GROQ:
// choices[0].message.content
//
// GEMINI:
// candidates[0].content.parts[0].text
//
// Also supports n8n wrapped responses.
// ================================================================

function extractText(response) {
  try {

    // ------------------------------------------------------------
    // GROQ / OPENAI-COMPATIBLE RESPONSE
    // ------------------------------------------------------------

    const groqContent =
      response?.choices?.[0]?.message?.content;

    if (typeof groqContent === "string") {
      return groqContent;
    }

    // ------------------------------------------------------------
    // GEMINI RESPONSE
    // ------------------------------------------------------------

    const geminiParts =
      response?.candidates?.[0]?.content?.parts;

    if (Array.isArray(geminiParts)) {

      const textPart = geminiParts.find(
        (p) => typeof p?.text === "string"
      );

      if (textPart) {
        return textPart.text;
      }
    }

    // ------------------------------------------------------------
    // N8N WRAPPED GROQ RESPONSE
    // ------------------------------------------------------------

    const wrappedGroqContent =
      response?.body?.choices?.[0]?.message?.content;

    if (typeof wrappedGroqContent === "string") {
      return wrappedGroqContent;
    }

    // ------------------------------------------------------------
    // N8N WRAPPED GEMINI RESPONSE
    // ------------------------------------------------------------

    const wrappedGeminiParts =
      response?.body?.candidates?.[0]?.content?.parts;

    if (Array.isArray(wrappedGeminiParts)) {

      const textPart = wrappedGeminiParts.find(
        (p) => typeof p?.text === "string"
      );

      if (textPart) {
        return textPart.text;
      }
    }

    return null;

  } catch (error) {

    return null;
  }
}


// ================================================================
// 4. SAFE JSON PARSER
// ================================================================

function safeParseJSON(text) {

  if (!text || typeof text !== "string") {
    return null;
  }

  let cleaned = text.trim();

  // Remove Markdown code fences if the model ignored JSON mode.
  cleaned = cleaned
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  // First attempt: direct JSON parse.
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    // Continue to recovery attempt.
  }

  // ------------------------------------------------------------
  // Recovery:
  // Sometimes a model may put a small amount of text around the
  // JSON object. Try extracting the outermost JSON object.
  // ------------------------------------------------------------

  const firstBrace = cleaned.indexOf("{");
  const lastBrace = cleaned.lastIndexOf("}");

  if (
    firstBrace !== -1 &&
    lastBrace !== -1 &&
    lastBrace > firstBrace
  ) {

    const possibleJSON =
      cleaned.slice(firstBrace, lastBrace + 1);

    try {
      return JSON.parse(possibleJSON);
    } catch (error) {
      return null;
    }
  }

  return null;
}


// ================================================================
// 5. COLLECT ALL DETERMINISTIC NUMBERS
// ================================================================
//
// Every numeric value generated by the deterministic engine is
// collected recursively.
//
// This allows us to verify figures mentioned by the LLM anywhere
// inside its recommendation.
// ================================================================

function collectEngineNumbers(
  value,
  numbers = new Set()
) {

  if (
    value === null ||
    value === undefined
  ) {
    return numbers;
  }

  if (
    typeof value === "number" &&
    Number.isFinite(value)
  ) {

    numbers.add(String(value));

    return numbers;
  }

  if (Array.isArray(value)) {

    for (const item of value) {
      collectEngineNumbers(item, numbers);
    }

    return numbers;
  }

  if (typeof value === "object") {

    for (const item of Object.values(value)) {
      collectEngineNumbers(item, numbers);
    }
  }

  return numbers;
}


// ================================================================
// 6. NORMALIZE NUMBERS
// ================================================================

function normalizeNumber(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  let stringValue = String(value)
    .replace(/[₹$€£]/g, "")
    .replace(/,/g, "")
    .trim();

  // Remove percentage sign.
  stringValue =
    stringValue.replace(/%$/, "");

  const numberValue =
    Number(stringValue);

  return Number.isFinite(numberValue)
    ? numberValue
    : null;
}


// ================================================================
// 7. EXTRACT NUMBERS FROM AI TEXT
// ================================================================
//
// Only figures >= 100 are checked.
//
// This avoids treating normal words such as:
// "3-month",
// "6-month",
// "50%",
// etc.
// as financial figures that need exact reconciliation.
//
// Financial figures such as:
// 121855.45
// 198144.55
// 1522272.5
// 2.31
// etc.
// are captured where appropriate.
// ================================================================

function extractNumbersFromText(text) {

  if (
    !text ||
    typeof text !== "string"
  ) {
    return [];
  }

  const regex =
    /(?:₹|\$|€|£)?-?\d[\d,]*(?:\.\d+)?%?/g;

  const matches =
    text.match(regex) || [];

  return matches
    .map(normalizeNumber)
    .filter(
      (numberValue) =>
        numberValue !== null
    )
    .filter(
      (numberValue) =>
        Math.abs(numberValue) >= 100
    );
}


// ================================================================
// 8. CHECK NUMBER AGAINST ENGINE
// ================================================================

function numberMatchesEngine(
  aiNumber,
  engineNumbers
) {

  for (const engineNumber of engineNumbers) {

    const deterministicNumber =
      Number(engineNumber);

    if (
      !Number.isFinite(
        deterministicNumber
      )
    ) {
      continue;
    }

    // Exact match.
    if (
      aiNumber === deterministicNumber
    ) {
      return true;
    }

    // Same absolute magnitude.
    //
    // This allows the AI to describe a reduction as a positive
    // figure even when the engine stores a signed delta.
    if (
      Math.abs(aiNumber) ===
      Math.abs(deterministicNumber)
    ) {
      return true;
    }

    // Small floating-point tolerance.
    if (
      Math.abs(
        Math.abs(aiNumber) -
        Math.abs(deterministicNumber)
      ) < 0.01
    ) {
      return true;
    }
  }

  return false;
}


// ================================================================
// 9. REQUIRED RECOMMENDATION STRUCTURE
// ================================================================

const REQUIRED_FIELDS = [
  "summaryForOwner",
  "primaryRecommendation",
  "alternativeOptions",
  "notPreferredOptions",
  "risksAndTradeoffs",
  "technicalDetails",
  "disclaimer",
];


// ================================================================
// 10. VALIDATE RECOMMENDATION
// ================================================================

function validateRecommendation(
  recommendationObject,
  engineContext,
  deterministicFin
) {

  const errors = [];

  // ------------------------------------------------------------
  // Basic object validation
  // ------------------------------------------------------------

  if (
    !recommendationObject ||
    typeof recommendationObject !== "object" ||
    Array.isArray(recommendationObject)
  ) {

    return {
      valid: false,
      errors: [
        "Recommendation is not a valid JSON object."
      ],
    };
  }


  // ------------------------------------------------------------
  // Required fields
  // ------------------------------------------------------------

  for (const field of REQUIRED_FIELDS) {

    if (
      !(field in recommendationObject)
    ) {

      errors.push(
        `Missing recommendation field: ${field}.`
      );
    }
  }


  // ------------------------------------------------------------
  // Primary recommendation
  // ------------------------------------------------------------

  if (
    recommendationObject.primaryRecommendation !==
    undefined
  ) {

    if (
      typeof recommendationObject.primaryRecommendation !==
      "object" ||
      Array.isArray(
        recommendationObject.primaryRecommendation
      )
    ) {

      errors.push(
        "primaryRecommendation must be an object."
      );

    } else {

      if (
        typeof recommendationObject
          .primaryRecommendation
          .title !== "string"
      ) {

        errors.push(
          "primaryRecommendation.title must be a string."
        );
      }

      if (
        typeof recommendationObject
          .primaryRecommendation
          .explanation !== "string"
      ) {

        errors.push(
          "primaryRecommendation.explanation must be a string."
        );
      }

      if (
        "supportingNumbers" in
        recommendationObject.primaryRecommendation &&
        !Array.isArray(
          recommendationObject
            .primaryRecommendation
            .supportingNumbers
        )
      ) {

        errors.push(
          "primaryRecommendation.supportingNumbers must be an array."
        );
      }
    }
  }


  // ------------------------------------------------------------
  // Array fields
  // ------------------------------------------------------------

  const arrayFields = [
    "alternativeOptions",
    "notPreferredOptions",
    "risksAndTradeoffs",
  ];

  for (const field of arrayFields) {

    if (
      field in recommendationObject &&
      !Array.isArray(
        recommendationObject[field]
      )
    ) {

      errors.push(
        `${field} must be an array.`
      );
    }
  }


  // ------------------------------------------------------------
  // Technical details
  // ------------------------------------------------------------

  if (
    recommendationObject.technicalDetails !==
    undefined
  ) {

    if (
      typeof recommendationObject.technicalDetails !==
        "object" ||
      Array.isArray(
        recommendationObject.technicalDetails
      )
    ) {

      errors.push(
        "technicalDetails must be an object."
      );
    }
  }


  // ============================================================
  // UNSAFE CERTAINTY CHECK
  // ============================================================
  //
  // We do NOT reject the word "guarantee" globally because the
  // disclaimer itself may correctly say "not a guarantee".
  //
  // We only reject statements that imply approval or success is
  // certain.
  // ============================================================

  const allText =
    JSON.stringify(
      recommendationObject
    ).toLowerCase();

  const unsafePatterns = [

    "guaranteed approval",

    "guaranteed to be approved",

    "will be approved",

    "approval is guaranteed",

    "approval is assured",

    "assured approval",

    "we guarantee approval",

    "i guarantee approval",

    "promise approval",

    "will definitely approve",

    "lender will approve",

    "bank will approve",

    "guaranteed acceptance",

    "will definitely accept",

    "certain to be approved",

    "certain approval",

    "approval is certain",

    "guarantees approval",

  ];

  for (
    const phrase of unsafePatterns
  ) {

    if (
      allText.includes(phrase)
    ) {

      errors.push(
        `Recommendation contains an unsafe certainty phrase: "${phrase}".`
      );
    }
  }


  // ============================================================
  // FINANCIAL NUMBER TRACEABILITY
  // ============================================================

  const engineNumbers =
    collectEngineNumbers(
      engineContext
    );

  const recommendationText =
    JSON.stringify(
      recommendationObject
    );

  const citedNumbers =
    extractNumbersFromText(
      recommendationText
    );

  const unverifiableNumbers =
    citedNumbers.filter(
      (numberValue) =>
        !numberMatchesEngine(
          numberValue,
          engineNumbers
        )
    );

  if (
    unverifiableNumbers.length > 0
  ) {

    const uniqueNumbers = [
      ...new Set(
        unverifiableNumbers.map(
          (numberValue) =>
            String(numberValue)
        )
      ),
    ];

    errors.push(
      "Recommendation cites financial figures not found in deterministic engine output: " +
      uniqueNumbers
        .slice(0, 15)
        .join(", ")
    );
  }


  // ============================================================
  // DETERMINISTIC ENGINE AVAILABILITY
  // ============================================================

  if (
    !deterministicFin ||
    typeof deterministicFin !== "object" ||
    Object.keys(
      deterministicFin
    ).length === 0
  ) {

    errors.push(
      "Deterministic financial engine context unavailable — recommendation cannot be safely verified."
    );
  }


  // ============================================================
  // FINAL VALIDATION RESULT
  // ============================================================

  return {
    valid:
      errors.length === 0,

    errors,
  };
}


