    'This is illustrative financial decision-support only. It is not a lender decision, loan approval, financial offer, guarantee, or financial advice. Actual restructuring terms depend on lender assessment, approval, and contractual terms.'

};


// ------------------------------------------------------------
// 28. LANGUAGE SAFETY CHECK
// ------------------------------------------------------------

const reportText =
  JSON.stringify(bankReport).toLowerCase();

const forbiddenClaims = [

  'post-restructuring solvency',

  'demonstrate solvency',

  'comfortably covers operating needs',

  'buffer for revenue volatility',

  'customers have not paid',

  'overdue customers',

  'overdue invoices',

  'fixed expenses',

  'remains manageable',

  'manageable emi',

  'comfortable emi',

  'affordable emi',

  'will prevent default',

  'will recover',

  'will collect',

  'customers will pay',

  'customers are expected to pay',

  'lender will approve',

  'bank will approve',

  'guaranteed approval',

  'guaranteed restructuring',

  'approved restructuring',

  'sanctioned restructuring'

];

const detectedForbiddenClaims =
  forbiddenClaims.filter(
    phrase =>
      reportText.includes(phrase)
  );


// ------------------------------------------------------------
// 29. RECOMMENDATION TRACEABILITY
// ------------------------------------------------------------

const recommendationScenarioFound =
  proposedRestructuringOptions.some(
    option =>
      String(option.option)
        .toLowerCase()
        .includes('50%')
  );


// ------------------------------------------------------------
// 30. ENGINE VALIDATION
// ------------------------------------------------------------

const requiredEngineFields = [

  'totalMonthlyEMI',

  'totalOutstandingDebt',

  'availableAfterExpenses',

  'availableAfterEMI',

  'internalDSCR'

];

const missingEngineFields =
  requiredEngineFields.filter(
    field =>
      financialEngine[field] === undefined ||
      financialEngine[field] === null
  );


// ------------------------------------------------------------
// 31. BASIC BANK REPORT VALIDATION
// ------------------------------------------------------------

const requiredReportFields = [

  'businessName',

  'date',

  'executiveSummary',

  'currentFinancialSnapshot',

  'keyIssues',

  'proposedRestructuringOptions',

  'riskAssessment',

  'requiredDocumentation',

  'nextSteps',

  'disclaimer'

];

const missingReportFields =
  requiredReportFields.filter(
    field =>
      !hasValue(bankReport[field])
  );


// ------------------------------------------------------------
// 32. VALIDATION ERRORS
// ------------------------------------------------------------

const errors = [];


// Parse error
if (!bankReportParsed) {

  errors.push(
    'Bank report could not be parsed from the AI response.'
  );

}


// Required fields
if (missingReportFields.length > 0) {

  errors.push(
    `Bank report is missing required fields: ${missingReportFields.join(', ')}`
  );

}


// Engine
if (missingEngineFields.length > 0) {

  errors.push(
    `Deterministic financial engine is missing required fields: ${missingEngineFields.join(', ')}`
  );

}


// Recommendation
if (
  recommendationValid &&
  !recommendationScenarioFound
) {

  errors.push(
    'The validated 50% tenure-extension scenario was not found in proposedRestructuringOptions.'
  );

}


// Unsafe language
if (detectedForbiddenClaims.length > 0) {

  errors.push(
    `Unsupported or unsafe language detected: ${detectedForbiddenClaims.join(', ')}`
  );

}


// Reconciliation
if (reconciliationConflicts.length > 0) {

  errors.push(
    `Reconciliation conflicts detected: ${reconciliationConflicts.length}`
  );

}


// ------------------------------------------------------------
// 33. FINAL VALIDATION STATUS
// ------------------------------------------------------------

const bankReportValid =
  errors.length === 0;

const validationPassed =
  bankReportValid &&
  financialEngineAvailable &&
  scenarioEngineAvailable;


// ------------------------------------------------------------
// 34. FINAL OUTPUT
// ------------------------------------------------------------

return [

  {

    json: {

      validationPassed,

      valid:
        validationPassed,

      systemStatus:
        validationPassed
          ? 'SUCCESS'
          : 'NEEDS_CONFIRMATION',

      errors,

      warnings: [],

      aiUnavailable:
        !bankReportParsed,

      bankReport:
        bankReportValid
          ? bankReport
          : null,

      bankReportValid,

      bankReportParsed,

      missingReportFields,

      parsedBankReport,

      financialEngine,

      deterministicEngineAvailable:
        financialEngineAvailable,

      missingEngineFields,

      deterministicSnapshot:
        currentFinancialSnapshot,

      scenarioBundle:
        rawScenarioBundle,

      scenarioEngineAvailable,

      scenarioSnapshot:
        scenarioBundle,

      reconciliation:
        reconciliationResults,

      reconciliationHasConflict:
        reconciliationConflicts.length > 0,

      reconciliationConflicts,

      classifications,

      dataConfidence,

      confidenceScore:
        dataConfidence.score ?? null,

      confidenceLevel:
        dataConfidence.level ?? null,

      validatedRecommendation,

      recommendationValid,

      recommendationValidation,

      finalReport: {

        bankReport:
          bankReportValid
            ? bankReport
            : null,

        recommendation:
          recommendationValid
            ? validatedRecommendation
            : null,

        financialSnapshot:
          currentFinancialSnapshot,

        scenarios:
          scenarioBundle,

        classifications,

        dataConfidence,

        validation: {

          passed:
            validationPassed,

          errors

        }

      },

      bankReportDiagnostic: {

        extractedTextFound:
          rawBankReportText.length > 0,

        extractedTextLength:
          rawBankReportText.length,

        parsedSuccessfully:
          bankReportParsed,

        expectedReportKeys:
          requiredReportFields,

        missingReportFields,

        financialEngineRecovered:
          financialEngineAvailable,

        scenarioBundleRecovered:
          scenarioEngineAvailable,

        recommendationRecovered:
          recommendationValid,

        recommendationScenarioFound,

        reconciliationConflictCount:
          reconciliationConflicts.length,

        classificationCount:
          classifications.length,

        languageCheckPassed:
          detectedForbiddenClaims.length === 0,

        detectedForbiddenClaims

      },

      debug: {

        currentInputKeys:
          Object.keys(input),

        engineNodeKeys:
          Object.keys(engineNode),

        engineFinFound:
          financialEngineAvailable,

        engineFinKeys:
          Object.keys(financialEngine),

        recommendationNodeKeys:
          Object.keys(recommendationNode),

        recommendationFound:
          recommendationValid,

        rawBankReportFound:
          rawBankReportText.length > 0,

        rawBankReportLength:
          rawBankReportText.length,

        bankReportParsed,

        bankReportValid,

        financialEngineFound:
          financialEngineAvailable,

        scenarioBundleFound:
          scenarioEngineAvailable,

        reconciliationFound:
          reconciliationResults.length > 0,

        classificationsFound:
          classifications.length > 0,

        dataConfidenceFound:
          nonEmptyObject(dataConfidence)

      },

      disclaimer:
        'RESTRUCTRA provides illustrative decision-support based on supplied information and deterministic calculations. It is not a lender decision, approval, offer, guarantee, or financial advice.'

    }

  }

];

// ============================================================
// RESTRUCTRA — ASSEMBLE FINAL RESPONSE
// V2 — FINAL DATA RECOVERY FIX
// ============================================================

function isObject(value) {
  return value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value);
}

function firstDefined(...values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }
  return null;
}

function firstObject(...values) {
  for (const value of values) {
    if (
      isObject(value) &&
      Object.keys(value).length > 0
    ) {
      return value;
    }
  }
  return {};
}

function firstArray(...values) {
  for (const value of values) {
    if (Array.isArray(value)) {
      return value;
    }
  }
  return [];
}


// ------------------------------------------------------------
// CURRENT INPUT
// ------------------------------------------------------------

const input = $input.first().json;


// ------------------------------------------------------------
// VALIDATED BANK REPORT
// ------------------------------------------------------------

const bankReport =
  firstObject(
    input.bankReport,
    input.finalReport?.bankReport
  );


// ------------------------------------------------------------
// VALIDATED RECOMMENDATION
// ------------------------------------------------------------

const recommendation =
  firstObject(
    input.validatedRecommendation,
    input.recommendation,
    input.finalReport?.recommendation
  );


// ------------------------------------------------------------
// DETERMINISTIC FINANCIAL ENGINE
// ------------------------------------------------------------

const financialEngine =
  firstObject(
    input.financialEngine,
    input.finalReport?.financialSnapshot
  );


// ------------------------------------------------------------
// SCENARIOS
// ------------------------------------------------------------

const scenarios =
  firstObject(
    input.scenarioBundle,
    input.scenarios,
    input.finalReport?.scenarios
  );


// ------------------------------------------------------------
// SOURCE ENGINE NODE
// ------------------------------------------------------------
//
// This is the authoritative upstream source for:
// - classifications
// - reconciliation
// - confidence
//
// Do NOT rely only on the validator's recovered copies,
// because those may intentionally be empty when the validator
// does not need them for pass/fail.
// ------------------------------------------------------------

let engine = {};

try {

  engine =
    $('04-06 Financial Engine, Scenarios, Diagnosis')
      .first()
      .json || {};

} catch (error) {

  engine = {};

}


// ------------------------------------------------------------
// CLASSIFICATIONS
// ------------------------------------------------------------

const classifications =
  firstArray(
    input.classifications,
    input.finalReport?.classifications,
    engine.classifications
  );


// ------------------------------------------------------------
// RECONCILIATION
// ------------------------------------------------------------

const reconciliationResults =
  firstArray(
    input.reconciliation?.results,
    input.reconciliationResults,
    engine.reconciliationResults
  );

const reconciliationConflicts =
  firstArray(
    input.reconciliation?.conflicts,
    engine.reconciliationResults
      ?.flatMap(r =>
        Array.isArray(r.conflicts)
          ? r.conflicts
          : []
      )
  );


// ------------------------------------------------------------
// BUILD RECONCILIATION OBJECT
// ------------------------------------------------------------

const reconciliation = {

  results:
    reconciliationResults,

  hasConflict:
    Boolean(
      input.reconciliation?.hasConflict
    ) ||
    reconciliationConflicts.length > 0,

  conflicts:
    reconciliationConflicts

};


// ------------------------------------------------------------
// DATA CONFIDENCE
// ------------------------------------------------------------

const dataConfidence =
  firstObject(
    input.dataConfidence,
    input.finalReport?.dataConfidence,
    engine.dataConfidence
  );


// ------------------------------------------------------------
// FINANCIAL SNAPSHOT
// ------------------------------------------------------------
//
// Keep the validated snapshot first.
// Then recover missing source fields if required.
// ------------------------------------------------------------

const validatedSnapshot =
  firstObject(
    input.deterministicSnapshot,
    input.financialSnapshot,
    input.finalReport?.financialSnapshot
  );

const sourceData =
  firstObject(
