      business.monthlySales
    ),

  monthlyExpenses:
    firstDefined(
      validatedSnapshot.monthlyExpenses,
      financialEngine.monthlyExpenses,
      business.monthlyExpenses
    ),

  cashReserve:
    firstDefined(
      validatedSnapshot.cashReserve,
      financialEngine.cashReserve,
      business.cashReserve
    ),

  receivables:
    firstDefined(
      validatedSnapshot.receivables,
      financialEngine.receivables,
      business.receivablesAmount,
      sourceData.receivablesAmount
    )

};


// ------------------------------------------------------------
// DASHBOARD
// ------------------------------------------------------------

const dashboard = {

  businessName:
    bankReport.businessName ||
    input.business?.name ||
    'Business',

  analysisDate:
    bankReport.date ||
    new Date().toISOString().slice(0, 10),

  financialHealth: {

    monthlySales:
      financialSnapshot.monthlySales,

    monthlyExpenses:
      financialSnapshot.monthlyExpenses,

    cashReserve:
      financialSnapshot.cashReserve,

    receivables:
      financialSnapshot.receivables,

    totalMonthlyEMI:
      financialSnapshot.totalMonthlyEMI ??
      financialEngine.totalMonthlyEMI,

    totalOutstandingDebt:
      financialSnapshot.totalOutstandingDebt ??
      financialEngine.totalOutstandingDebt,

    availableAfterExpenses:
      financialSnapshot.availableAfterExpenses ??
      financialEngine.availableAfterExpenses,

    availableAfterEMI:
      financialSnapshot.availableAfterEMI ??
      financialEngine.availableAfterEMI,

    internalDSCR:
      financialSnapshot.internalDSCR ??
      financialEngine.internalDSCR,

    emiToSalesRatio:
      financialSnapshot.emiToSalesRatio ??
      financialEngine.emiToSalesRatio,

    emiToAvailableRatio:
      financialSnapshot.emiToAvailableRatio ??
      financialEngine.emiToAvailableRatio,

    cashReserveCoverageMonths:
      financialSnapshot.cashReserveCoverageMonths ??
      financialEngine.cashReserveCoverageMonths,

    receivablesRatio:
      financialSnapshot.receivablesRatio ??
      financialEngine.receivablesRatio,

