      financialEngine.weightedAvgInterestRate,

    weightedAvgTenureMonths:
      financialSnapshot.weightedAvgTenureMonths ??
      financialEngine.weightedAvgTenureMonths

  },


  // ----------------------------------------------------------
  // STRESS DIAGNOSIS
  // ----------------------------------------------------------

  stressDiagnosis: {

    classifications,

    currentSurplus:
      scenarios.current
        ?.monthlySurplusDeficit
        ?.base ?? null,

    stressSurplus:
      scenarios.current
        ?.monthlySurplusDeficit
        ?.stress ?? null,

    recoverySurplus:
      scenarios.current
        ?.monthlySurplusDeficit
        ?.recovery ?? null,

