      scenarios.stressAssumptions
        ?.stressRevenueChangePct ?? null,

    recoveryRevenueChangePct:
      scenarios.stressAssumptions
        ?.recoveryRevenueChangePct ?? null

  },


  // ----------------------------------------------------------
  // RESTRUCTURING
  // ----------------------------------------------------------

