        bankReportRecovered:
          Object.keys(bankReport).length > 0,

        sourceDataRecovered:
          Object.keys(sourceData).length > 0,

        financialSnapshotRecovered:
          Object.keys(financialSnapshot).length > 0,

        criticalFinancialFieldsPresent:
          financialSnapshot.monthlySales !== null &&
          financialSnapshot.monthlyExpenses !== null &&
          financialSnapshot.cashReserve !== null &&
          financialSnapshot.receivables !== null,

        finalValidation:
          input.validationPassed === true

      },


      disclaimer:
        'RESTRUCTRA provides illustrative decision-support based on supplied information and deterministic calculations. It is not a lender decision, approval, offer, guarantee, or financial advice.'

    }

  }

];

