// Split multipart uploads into one binary item per document.
// React sends questionnaire JSON in `payload` and files in multipart `documents`.
const input = $input.first();
const body = input.json?.body ?? input.json ?? {};
let payload = body.payload ?? body;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch { payload = {}; }
}
const binaries = input.binary || {};
const entries = Object.entries(binaries);

const supported = new Set(['txt','text','csv','pdf','xlsx','xls','ods','rtf','html','json','xml']);

if (!entries.length) {
  return [{ json: { ...payload, __hasUploads: false, __document: null } }];
}

const out = [];
for (const [propertyName, binary] of entries) {
  const fileName = binary?.fileName || propertyName;
  const mimeType = binary?.mimeType || null;
  const ext = String(fileName).split('.').pop().toLowerCase();
  const operation = ext === 'text' ? 'text' : ext;
  const extractionSupported = supported.has(operation);

  out.push({
    json: {
      ...payload,
      __hasUploads: true,
      __document: {
        fileName,
        mimeType,
        size: binary?.fileSize || null,
        extractionOperation: operation,
        extractionSupported,
      },
    },
    binary: { data: binary },
  });
}
return out;

// Aggregate extracted documents back into one questionnaire payload.
// Each extractor has a FIXED operation; routing happens before this node.
const items = $input.all();
const first = items[0]?.json || {};
const payload = { ...first };
delete payload.__document;
delete payload.__hasUploads;

function num(v){
  if(v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[₹,\s]/g,''));
  return Number.isFinite(n) ? n : null;
}
function field(field, value, source, confidence=0.82){
  const n = num(value);
  return { field, value: n ?? value, source, confidence };
}
function extractFields(text, fileName){
  const t = String(text || '').replace(/\r/g,'');
  const fields=[];
  const patterns=[
    ['monthlyEMI',/(?:total\s+)?monthly\s+(?:emi|installment|instalment)\s*[:=\-]?\s*[₹rs\.\s]*([\d,]+(?:\.\d+)?)/i],
    ['monthlyEMI',/emi\s*(?:per\s+month|monthly)?\s*[:=\-]?\s*[₹rs\.\s]*([\d,]+(?:\.\d+)?)/i],
    ['totalOutstanding',/(?:total\s+)?(?:outstanding|principal\s+outstanding|loan\s+outstanding)\s*(?:amount)?\s*[:=\-]?\s*[₹rs\.\s]*([\d,]+(?:\.\d+)?)/i],
    ['monthlySales',/(?:monthly\s+)?(?:sales|revenue|turnover)\s*(?:per\s+month|monthly)?\s*[:=\-]?\s*[₹rs\.\s]*([\d,]+(?:\.\d+)?)/i],
    ['monthlyExpenses',/(?:monthly\s+)?(?:expenses|operating\s+expenses|costs)\s*(?:per\s+month|monthly)?\s*[:=\-]?\s*[₹rs\.\s]*([\d,]+(?:\.\d+)?)/i],
    ['receivables',/(?:accounts?\s+receivable|receivables|customer\s+dues|amount\s+receivable)\s*[:=\-]?\s*[₹rs\.\s]*([\d,]+(?:\.\d+)?)/i],
  ];
  for(const [name,re] of patterns){
    const m=t.match(re); if(m) fields.push(field(name,m[1],fileName,0.86));
  }
  const totalEmi=t.match(/total\s+(?:monthly\s+)?emi\s*[:=\-]?\s*[₹rs\.\s]*([\d,]+(?:\.\d+)?)/i);
  if(totalEmi){ for(let i=fields.length-1;i>=0;i--) if(fields[i].field==='monthlyEMI') fields.splice(i,1); fields.push(field('monthlyEMI',totalEmi[1],fileName,0.94)); }
  const totalOut=t.match(/total\s+(?:loan\s+)?outstanding\s*(?:amount)?\s*[:=\-]?\s*[₹rs\.\s]*([\d,]+(?:\.\d+)?)/i);
  if(totalOut) fields.push(field('totalOutstanding',totalOut[1],fileName,0.94));
  return fields;
}

const grouped=new Map();
function getDoc(meta){
  const key=meta.fileName || `document_${grouped.size+1}`;
  if(!grouped.has(key)) grouped.set(key,{fileName:key,documentType:meta.extractionOperation||'unknown',mimeType:meta.mimeType||null,fields:[],extractionFailed:false});
  return grouped.get(key);
}

for(const item of items){
  const j=item.json||{};
  const meta=j.__document||{};
  const doc=getDoc(meta);

  if(meta.extractionSupported===false){
    doc.extractionFailed=true;
    doc.extractionError='Unsupported file type. Supported: PDF, XLSX, XLS, CSV, TXT, ODS, RTF, HTML, JSON, XML.';
    continue;
  }

  let text='';
  if(typeof j.text==='string') text=j.text;
  else if(typeof j.data==='string') text=j.data;
  else {
    const clone={...j};
    delete clone.__document; delete clone.__hasUploads;
    text=JSON.stringify(clone);
  }

  if(text.trim()) doc.fields.push(...extractFields(text,doc.fileName));
}

for(const doc of grouped.values()){
  const best=new Map();
  for(const f of doc.fields){ const old=best.get(f.field); if(!old || f.confidence>old.confidence) best.set(f.field,f); }
  doc.fields=[...best.values()];
  if(!doc.fields.length && !doc.extractionFailed){
    doc.extractionFailed=true;
    doc.extractionError='The document was extracted, but no supported financial fields were confidently identified.';
  }
}

payload.documents=[...grouped.values()];
payload.documentExtraction={
  attempted:true,
  documentCount:payload.documents.length,
  successful:payload.documents.filter(d=>!d.extractionFailed).length,
  failed:payload.documents.filter(d=>d.extractionFailed).length,
};
return [{json:payload}];
